import{_ as e,o as t,c as s,a2 as i}from"./chunks/framework.CqGPl1zp.js";const k=JSON.parse('{"title":"【模型接入】阶跃星辰","description":"","frontmatter":{},"headers":[],"relativePath":"ai/stepfun.md","filePath":"ai/stepfun.md","lastUpdated":null}'),l={name:"ai/stepfun.md"};function n(p,a,d,h,o,r){return t(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="【模型接入】阶跃星辰" tabindex="-1">【模型接入】阶跃星辰 <a class="header-anchor" href="#【模型接入】阶跃星辰" aria-label="Permalink to &quot;【模型接入】阶跃星辰&quot;">​</a></h1><p>项目基于 Spring AI + 自己实现的 <code>models/stepfun</code>，实现 <a href="https://www.stepfun.com/" target="_blank" rel="noreferrer">阶跃星辰</a> 的接入，底层复用兼容 OpenAI 协议的客户端：</p><table tabindex="0"><thead><tr><th>功能</th><th>模型</th><th>Spring AI 客户端</th></tr></thead><tbody><tr><td>AI 对话</td><td>step-3.7-flash</td><td>StepFunChatModel</td></tr><tr><td>AI 绘画</td><td>暂未接入</td><td>暂未接入</td></tr></tbody></table><h2 id="_1-申请密钥" tabindex="-1">1. 申请密钥 <a class="header-anchor" href="#_1-申请密钥" aria-label="Permalink to &quot;1. 申请密钥&quot;">​</a></h2><p>阶跃星辰提供官方 API 服务，可以直接申请 API Key 使用。</p><p>① 在 <a href="https://platform.stepfun.com/" target="_blank" rel="noreferrer">阶跃星辰开放平台</a> 上，注册一个账号。</p><p>② 在 <a href="https://platform.stepfun.com/interface-key" target="_blank" rel="noreferrer">接口密钥</a> 页面，创建一个 API Key 密钥。</p><hr><p>申请完成后，可以在我们系统的 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单，进行密钥的配置，字段可以按下面填写：</p><ul><li>名称：<code>阶跃星辰</code></li><li>所属平台：<code>StepFun</code></li><li>API 密钥：填写上一步创建的阶跃星辰 API Key</li><li>自定义 API URL：不填写，项目默认使用阶跃星辰官方地址</li></ul><h2 id="_2-模型配置" tabindex="-1">2. 模型配置 <a class="header-anchor" href="#_2-模型配置" aria-label="Permalink to &quot;2. 模型配置&quot;">​</a></h2><p>友情提示：</p><p>目前 <code>ai_model</code> 表中，已经预置了一些模型，可以直接使用！！！</p><h3 id="_2-1-ai-对话" tabindex="-1">2.1 AI 对话 <a class="header-anchor" href="#_2-1-ai-对话" aria-label="Permalink to &quot;2.1 AI 对话&quot;">​</a></h3><p>使用 <a href="./chat">《AI 对话》</a> 时，需要在 [AI 大模型 -&gt; 控制台 -&gt; 模型配置] 菜单，配置对应的聊天模型，字段可以按下面填写：</p><ul><li>模型名称：<code>step-3.7-flash</code></li><li>所属平台：<code>StepFun</code></li><li>模型类型：<code>聊天</code></li><li>模型标识：<code>step-3.7-flash</code></li><li>API 密钥：选择前面配置的阶跃星辰密钥</li><li>回复数 Token 数：<code>256000</code></li></ul><p>不同模型的 <code>max_tokens</code>（回复数 Token 数）上限不同，可以参考下表填写：</p><table tabindex="0"><thead><tr><th>模型标识</th><th><code>max_tokens</code> 最大输出 Tokens</th></tr></thead><tbody><tr><td><code>step-3.7-flash</code></td><td>256000</td></tr></tbody></table><h3 id="_2-2-ai-绘图" tabindex="-1">2.2 AI 绘图 <a class="header-anchor" href="#_2-2-ai-绘图" aria-label="Permalink to &quot;2.2 AI 绘图&quot;">​</a></h3><p>TODO 等待 StepFun ImageModel 客户端！</p><h2 id="_3-如何使用" tabindex="-1">3. 如何使用？ <a class="header-anchor" href="#_3-如何使用" aria-label="Permalink to &quot;3. 如何使用？&quot;">​</a></h2><p>① 如果你的项目里需要直接通过 <code>@Resource</code> 注入 StepFunChatModel 等对象，需要把 <code>application.yaml</code> 配置文件里的 <code>yudao.ai.stepfun</code> 配置项，替换成你的！</p><div class="language-YAML vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">YAML</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">yudao</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ai</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    stepfun</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 阶跃星辰</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      enable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      api-key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${STEPFUN_API_KEY}</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">step-3.7-flash</span></span></code></pre></div><p>② 如果你希望使用 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单的密钥配置，则可以通过 AiModelService 的 <code>#getChatModel(...)</code> 方法，获取对应的模型对象。</p><hr><p>① 和 ② 这两者的后续使用，就是标准的 Spring AI 客户端的使用，调用对应的方法即可。</p><p>另外，StepFunChatModelTests 里有对应的测试用例，可以参考。</p>`,27)])])}const u=e(l,[["render",n]]);export{k as __pageData,u as default};
